<script>
(function(){
  "use strict";

  /* ---------- palettes ---------- */
  const PALETTES = {
    hero:   { light:'#fdf1c9', mid:'#cf9d3f', dark:'#5c3f14' },
    bronze: { light:'#e8b27a', mid:'#9c6b3e', dark:'#432711' },
    silver: { light:'#f7f9fb', mid:'#b9c0c6', dark:'#4b5155' },
    gold:   { light:'#fff2b8', mid:'#d4af37', dark:'#6b4e10' },
    black:  { light:'#9b93c9', mid:'#26232d', dark:'#08080a' }
  };

  /* ---------- small drawing helpers ---------- */
  function arcText(ctx, text, cx, cy, radius, centerAngle, totalAngle, opts){
    opts = opts || {};
    ctx.save();
    ctx.font = opts.font || '20px Georgia';
    ctx.fillStyle = opts.color || '#000';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    const n = text.length;
    if(n === 0){ ctx.restore(); return; }
    const startAngle = centerAngle - totalAngle/2;
    const step = n > 1 ? totalAngle/(n-1) : 0;
    for(let i=0;i<n;i++){
      const a = startAngle + step*i;
      const x = cx + Math.cos(a)*radius;
      const y = cy + Math.sin(a)*radius;
      ctx.save();
      ctx.translate(x,y);
      ctx.rotate(a + Math.PI/2 + (opts.flip ? Math.PI : 0));
      ctx.fillText(text[i], 0, 0);
      ctx.restore();
    }
    ctx.restore();
  }

  function drawStar(ctx, x, y, R, r, points, color){
    ctx.save();
    ctx.translate(x,y);
    ctx.beginPath();
    for(let i=0;i<points*2;i++){
      const rad = (i%2===0) ? R : r;
      const a = Math.PI*i/points - Math.PI/2;
      const px = Math.cos(a)*rad, py = Math.sin(a)*rad;
      if(i===0) ctx.moveTo(px,py); else ctx.lineTo(px,py);
    }
    ctx.closePath();
    ctx.fillStyle = color;
    ctx.fill();
    ctx.restore();
  }

  /* build a face texture (front emblem OR back denomination) once, offscreen */
  function buildFace(size, palette, mode, opts){
    opts = opts || {};
    const canvas = document.createElement('canvas');
    canvas.width = canvas.height = size;
    const ctx = canvas.getContext('2d');
    const cx = size/2, cy = size/2, r = size/2 - size*0.02;

    // base metal field
    const g = ctx.createRadialGradient(cx-r*0.35, cy-r*0.35, r*0.04, cx, cy, r);
    g.addColorStop(0, palette.light);
    g.addColorStop(0.55, palette.mid);
    g.addColorStop(1, palette.dark);
    ctx.fillStyle = g;
    ctx.beginPath(); ctx.arc(cx,cy,r,0,Math.PI*2); ctx.fill();

    // denticle ring (rim beads)
    const nD = 64;
    for(let i=0;i<nD;i++){
      const a = i/nD*Math.PI*2;
      const rr = r*0.93;
      ctx.save();
      ctx.translate(cx+Math.cos(a)*rr, cy+Math.sin(a)*rr);
      ctx.rotate(a);
      ctx.fillStyle = (i%2===0) ? palette.light : palette.dark;
      ctx.fillRect(-size*0.006, -size*0.02, size*0.012, size*0.04);
      ctx.restore();
    }

    // rim rings
    ctx.lineWidth = r*0.05;
    ctx.strokeStyle = palette.dark;
    ctx.beginPath(); ctx.arc(cx,cy,r*0.85,0,Math.PI*2); ctx.stroke();
    ctx.lineWidth = r*0.014;
    ctx.strokeStyle = palette.light;
    ctx.beginPath(); ctx.arc(cx,cy,r*0.82,0,Math.PI*2); ctx.stroke();

    // arc legends
    arcText(ctx, opts.top || '', cx, cy, r*0.71, -Math.PI/2, Math.PI*0.92,
      {font:`bold ${Math.round(size*0.042)}px Georgia`, color:palette.dark});
    arcText(ctx, opts.bottom || '', cx, cy, r*0.71, Math.PI/2, Math.PI*0.62,
      {font:`bold ${Math.round(size*0.038)}px Georgia`, color:palette.dark, flip:true});

    drawStar(ctx, cx - r*0.71, cy, r*0.045, r*0.02, 5, palette.dark);
    drawStar(ctx, cx + r*0.71, cy, r*0.045, r*0.02, 5, palette.dark);

    if(mode === 'front'){
      // recessed medallion
      const rg = ctx.createRadialGradient(cx,cy,r*0.05, cx,cy,r*0.48);
      rg.addColorStop(0, palette.dark);
      rg.addColorStop(1, palette.mid);
      ctx.fillStyle = rg;
      ctx.beginPath(); ctx.arc(cx,cy,r*0.48,0,Math.PI*2); ctx.fill();
      ctx.lineWidth = r*0.02;
      ctx.strokeStyle = palette.light;
      ctx.beginPath(); ctx.arc(cx,cy,r*0.48,0,Math.PI*2); ctx.stroke();

      // monogram with fake bevel (offset shadow / highlight / base)
      const fs = r*0.62;
      ctx.font = `bold ${fs}px Georgia`;
      ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
      const mx = cx, my = cy - r*0.04;
      ctx.fillStyle = palette.dark;  ctx.fillText('W', mx + r*0.022, my + r*0.03);
      ctx.fillStyle = palette.light; ctx.fillText('W', mx - r*0.018, my - r*0.024);
      ctx.fillStyle = palette.mid;   ctx.fillText('W', mx, my);

      ctx.font = `bold ${Math.round(size*0.032)}px Georgia`;
      ctx.fillStyle = palette.dark;
      ctx.fillText(opts.sub || '', cx, cy + r*0.58);
    } else {
      // denomination back
      ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
      let fs = r*0.46;
      const big = opts.big || '10,000';
      ctx.font = `bold ${fs}px Georgia`;
      let tw = ctx.measureText(big).width;
      const maxW = r*1.35;
      if(tw > maxW){ fs *= maxW/tw; ctx.font = `bold ${fs}px Georgia`; }
      const my = cy - r*0.06;
      ctx.fillStyle = palette.dark;  ctx.fillText(big, cx + r*0.022, my + r*0.03);
      ctx.fillStyle = palette.light; ctx.fillText(big, cx - r*0.018, my - r*0.024);
      ctx.fillStyle = palette.mid;   ctx.fillText(big, cx, my);

      ctx.font = `bold ${Math.round(size*0.05)}px Georgia`;
      ctx.fillStyle = palette.dark;
      ctx.fillText(opts.sub || 'TOKENS', cx, cy + r*0.26);

      ctx.strokeStyle = palette.dark;
      ctx.lineWidth = r*0.014;
      ctx.beginPath();
      ctx.moveTo(cx - r*0.32, cy + r*0.4); ctx.lineTo(cx + r*0.32, cy + r*0.4);
      ctx.stroke();
    }
    return canvas;
  }

  /* ---------- master coin renderer (used by hero + editions) ---------- */
  function drawCoin(ctx, cx, cy, radius, angleY, angleX, frontTex, backTex, opts){
    opts = opts || {};
    const thickness = opts.thickness || radius*0.16;
    const cosY = Math.cos(angleY), sinY = Math.sin(angleY);
    const cosX = Math.cos(angleX);

    const ew = radius * Math.abs(cosY);
    const eh = radius * Math.max(0.001, cosX);

    // soft ground shadow
    const shG = ctx.createRadialGradient(cx, cy+radius*0.92, radius*0.05, cx, cy+radius*0.92, radius*0.95);
    shG.addColorStop(0, 'rgba(0,0,0,0.42)');
    shG.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = shG;
    ctx.beginPath();
    ctx.ellipse(cx, cy+radius*0.92, radius*0.95, radius*0.22, 0, 0, Math.PI*2);
    ctx.fill();

    // reeded edge (visible strongly when face-on width collapses)
    const edgeW = Math.max(0, thickness*Math.abs(sinY));
    if(edgeW > 1.2){
      const stripes = 18;
      const grad = ctx.createLinearGradient(cx-edgeW/2, 0, cx+edgeW/2, 0);
      for(let i=0;i<=stripes;i++){
        const p = i/stripes;
        grad.addColorStop(p, (i%2===0) ? 'rgba(255,255,255,0.55)' : 'rgba(0,0,0,0.55)');
      }
      ctx.save();
      ctx.fillStyle = grad;
      ctx.fillRect(cx-edgeW/2, cy-eh, edgeW, eh*2);
      ctx.globalAlpha = 0.55;
      ctx.fillStyle = '#8a7440';
      ctx.fillRect(cx-edgeW/2, cy-eh, edgeW, eh*2);
      ctx.globalAlpha = 1;
      const shade = ctx.createLinearGradient(0, cy-eh, 0, cy+eh);
      shade.addColorStop(0, 'rgba(255,255,255,0.35)');
      shade.addColorStop(0.5, 'rgba(255,255,255,0)');
      shade.addColorStop(1, 'rgba(0,0,0,0.4)');
      ctx.fillStyle = shade;
      ctx.fillRect(cx-edgeW/2, cy-eh, edgeW, eh*2);
      ctx.restore();
    }

    // face
    if(ew > 0.6){
      const isFront = cosY >= 0;
      const tex = isFront ? frontTex : backTex;

      ctx.save();
      ctx.beginPath();
      ctx.ellipse(cx, cy, ew, eh, 0, 0, Math.PI*2);
      ctx.clip();

      ctx.drawImage(tex, cx-ew, cy-eh, ew*2, eh*2);

      // moving specular highlight — sweeps across the face as angleY changes
      const hlx = cx + Math.sin(angleY*2) * ew * 0.72;
      const hly = cy + Math.sin(angleX) * eh * 0.35;
      const hlR = Math.max(ew, eh)*0.55 + 8;
      const hg = ctx.createRadialGradient(hlx, hly, 0, hlx, hly, hlR);
      hg.addColorStop(0, 'rgba(255,255,255,0.88)');
      hg.addColorStop(0.35, 'rgba(255,255,255,0.28)');
      hg.addColorStop(1, 'rgba(255,255,255,0)');
      ctx.globalCompositeOperation = 'screen';
      ctx.fillStyle = hg;
      ctx.beginPath(); ctx.ellipse(cx, cy, ew, eh, 0, 0, Math.PI*2); ctx.fill();
      ctx.globalCompositeOperation = 'source-over';

      // rim darkening for roundness
      const rim = ctx.createRadialGradient(cx, cy, Math.min(ew,eh)*0.55, cx, cy, Math.max(ew,eh));
      rim.addColorStop(0, 'rgba(0,0,0,0)');
      rim.addColorStop(1, 'rgba(0,0,0,0.38)');
      ctx.fillStyle = rim;
      ctx.beginPath(); ctx.ellipse(cx, cy, ew, eh, 0, 0, Math.PI*2); ctx.fill();

      ctx.restore();

      ctx.save();
      ctx.strokeStyle = 'rgba(0,0,0,0.45)';
      ctx.lineWidth = 1.4;
      ctx.beginPath(); ctx.ellipse(cx, cy, ew, eh, 0, 0, Math.PI*2); ctx.stroke();
      ctx.restore();
    }
  }

  function drawRibbon(ctx, w, h, text, bg){
    ctx.save();
    ctx.translate(w/2, h/2);
    ctx.rotate(-Math.PI/8);
    ctx.fillStyle = bg;
    ctx.fillRect(-w*0.72, -h*0.095, w*1.44, h*0.19);
    ctx.strokeStyle = 'rgba(255,255,255,0.55)';
    ctx.lineWidth = 1;
    ctx.strokeRect(-w*0.72, -h*0.095, w*1.44, h*0.19);
    ctx.fillStyle = '#fff';
    ctx.font = `bold ${Math.round(h*0.075)}px Arial, sans-serif`;
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.fillText(text, 0, 2);
    ctx.restore();
  }

  function heroBackdrop(ctx, w, h){
    const g = ctx.createRadialGradient(w/2, h*0.42, 10, w/2, h/2, w*0.66);
    g.addColorStop(0, '#20242c');
    g.addColorStop(1, '#0a0b0d');
    ctx.fillStyle = g;
    ctx.fillRect(0,0,w,h);
    ctx.strokeStyle = 'rgba(255,255,255,0.045)';
    ctx.lineWidth = 1;
    for(let i=1;i<=3;i++){
      ctx.beginPath();
      ctx.arc(w/2, h/2, w*0.2*i, 0, Math.PI*2);
      ctx.stroke();
    }
  }

  /* ---------- hero coin setup ---------- */
  const heroCanvas = document.getElementById('coin-hero');
  const hctx = heroCanvas.getContext('2d');
  const HW = heroCanvas.width, HH = heroCanvas.height;
  const HERO_R = 190;

  const heroFront = buildFace(560, PALETTES.hero, 'front', {
    top: 'WASTEDTOKEN MINT', bottom: 'FINE STRIKE', sub: 'MINT MARK · WM'
  });
  const heroBack = buildFace(560, PALETTES.hero, 'back', {
    top: 'LIMITED MINTAGE', bottom: '★ WASTEDTOKEN ★', big: '10,000', sub: 'TOKENS'
  });

  function renderHero(t){
    const angleY = t * Math.PI * 2;
    const angleX = Math.sin(t * Math.PI * 4) * 0.8;
    hctx.clearRect(0,0,HW,HH);
    heroBackdrop(hctx, HW, HH);
    drawCoin(hctx, HW/2, HH/2, HERO_R, angleY, angleX, heroFront, heroBack, {thickness: HERO_R*0.17});
  }

  let playing = true;
  let rafId = null;
  let heroStart = null;
  const LOOP_MS = 9000;

  function loop(ts){
    if(!playing) return;
    if(heroStart === null) heroStart = ts;
    const t = ((ts - heroStart) % LOOP_MS) / LOOP_MS;
    renderHero(t);
    rafId = requestAnimationFrame(loop);
  }
  rafId = requestAnimationFrame(loop);

  window.demo = {
    canvas: heroCanvas,
    setTime: function(t){
      playing = false;
      if(rafId){ cancelAnimationFrame(rafId); rafId = null; }
      const tt = ((t % 1) + 1) % 1;
      renderHero(tt);
    },
    pause: function(){
      playing = false;
      if(rafId){ cancelAnimationFrame(rafId); rafId = null; }
    }
  };

  /* ---------- collection tiles ---------- */
  const editionsData = {
    bronze: { palette: PALETTES.bronze, big: '10,000', state: 'available' },
    silver: { palette: PALETTES.silver, big: '5,000',  state: 'available' },
    gold:   { palette: PALETTES.gold,   big: '1,000',  state: 'sold-out' },
    black:  { palette: PALETTES.black,  big: '2,500',  state: 'coming-soon' }
  };

  document.querySelectorAll('.edition').forEach(function(el){
    const key = el.getAttribute('data-edition');
    const data = editionsData[key];
    if(!data) return;
    const canvas = el.querySelector('.edition-canvas');
    const ctx = canvas.getContext('2d');
    const w = canvas.width, h = canvas.height;

    const front = buildFace(420, data.palette, 'front', {
      top: 'WASTEDTOKEN MINT', bottom: key.toUpperCase() + ' EDITION', sub: key.toUpperCase()
    });
    const back = buildFace(420, data.palette, 'back', {
      top: 'LIMITED MINTAGE', bottom: '★ WASTEDTOKEN ★', big: data.big, sub: 'TOKENS'
    });

    const phase = Math.random() * Math.PI * 2;
    const speed = 0.00032;

    function tick(ts){
      const angleY = phase + ts * speed;
      const angleX = Math.sin(ts * speed * 2.1) * 0.7;
      ctx.clearRect(0,0,w,h);
      drawCoin(ctx, w/2, h/2, 128, angleY, angleX, front, back, {thickness: 128*0.17});

      if(data.state === 'sold-out'){
        ctx.fillStyle = 'rgba(70,70,70,0.32)';
        ctx.fillRect(0,0,w,h);
        drawRibbon(ctx, w, h, 'SOLD OUT', 'rgba(30,20,20,0.62)');
      } else if(data.state === 'coming-soon'){
        ctx.fillStyle = 'rgba(30,25,50,0.18)';
        ctx.fillRect(0,0,w,h);
        drawRibbon(ctx, w, h, 'WINTER 2025', 'rgba(24,22,48,0.58)');
      }
      requestAnimationFrame(tick);
    }
    requestAnimationFrame(tick);
  });

})();
</script>
